string word = "banana";
var cnt = new Dictionary<char, int>();
foreach (char ch in word) {
    if (cnt.ContainsKey(ch)) cnt[ch]++;
    else cnt[ch] = 1;
}
foreach (var kv in cnt) Console.WriteLine(kv.Key + ":" + kv.Value);

